package dev.neureal.agenthq

import dev.neureal.agenthq.crypto.FrameCrypto
import dev.neureal.agenthq.crypto.deriveSessionKeys
import dev.neureal.agenthq.crypto.unb64
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test

// Interop against vectors generated by the hub's REAL session code
// (packages/hub/test/gen-session-vectors.ts). If this passes, the phone and
// the hub derive identical keys and can open each other's frames.
class SessionInteropTest {

    private fun vectors(): JSONObject {
        val stream = javaClass.getResourceAsStream("/session-vectors.json")
            ?: error("session-vectors.json missing — run: npx tsx test/gen-session-vectors.ts (from packages/hub)")
        return JSONObject(stream.readBytes().toString(Charsets.UTF_8))
    }

    @Test
    fun `derives the same session keys as the hub`() {
        val v = vectors()
        val keys = deriveSessionKeys(
            ownStaticPrivate = unb64(v.getString("deviceStaticPrivateRawB64")),
            peerStaticPublicRaw = unb64(v.getString("pcStaticPublicRawB64")),
            ownEphemeralPrivate = unb64(v.getString("deviceEphemeralPrivateRawB64")),
            peerEphemeralPublicRaw = unb64(v.getString("pcEphemeralPublicRawB64")),
            salt = unb64(v.getString("saltB64")),
        )
        assertEquals(v.getString("clientToServerKeyB64"), java.util.Base64.getEncoder().encodeToString(keys.clientToServer))
        assertEquals(v.getString("serverToClientKeyB64"), java.util.Base64.getEncoder().encodeToString(keys.serverToClient))
    }

    @Test
    fun `opens a hub-sealed frame and seals identically to the hub`() {
        val v = vectors()
        val crypto = FrameCrypto(
            sendKey = unb64(v.getString("clientToServerKeyB64")),
            recvKey = unb64(v.getString("serverToClientKeyB64")),
        )
        val opened = crypto.open(v.getString("serverFrameN"), v.getString("serverFrameC"))
        assertNotNull("failed to decrypt the hub's frame", opened)
        assertEquals(v.getString("serverPlaintext"), opened)

        val (nonce, ciphertext) = crypto.seal(v.getString("clientPlaintext"))
        assertEquals(v.getString("expectedClientFrameN"), nonce)
        assertEquals(v.getString("expectedClientFrameC"), ciphertext)
    }
}
